from collections import deque
def f(grid):
    h,w=len(grid),len(grid[0])
    # BFS depth from background (0 cells)
    dist=[[None]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in range(w):
            if grid[i][j]==0:
                dist[i][j]=0; q.append((i,j))
    for i,j in list(q):
        pass
    q=deque((i,j) for i in range(h) for j in range(w) if grid[i][j]==0)
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and dist[ni][nj] is None:
                dist[ni][nj]=dist[i][j]+1; q.append((ni,nj))
    # connected components of nonzero
    lab=[[-1]*w for _ in range(h)]; n=0
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and lab[i][j]==-1:
                qq=deque([(i,j)]); lab[i][j]=n
                while qq:
                    a,b=qq.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and grid[na][nb]!=0 and lab[na][nb]==-1:
                            lab[na][nb]=n; qq.append((na,nb))
                n+=1
    # per component: depth->color, max depth
    cmap=[{} for _ in range(n)]; dmax=[0]*n
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0:
                L=lab[i][j]; dpt=dist[i][j]
                cmap[L].setdefault(dpt,grid[i][j])
                dmax[L]=max(dmax[L],dpt)
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0:
                L=lab[i][j]; dpt=dist[i][j]
                out[i][j]=cmap[L][dmax[L]-dpt]
    return out

