def rings(grid):
    h,w=len(grid),len(grid[0])
    lab=[[-1]*w for _ in range(h)]; n=0
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and lab[i][j]==-1:
                qq=deque([(i,j)]); lab[i][j]=n
                while qq:
                    a,b=qq.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and grid[na][nb]!=0 and lab[na][nb]==-1:
                            lab[na][nb]=n; qq.append((na,nb))
                n+=1
    cells=[set() for _ in range(n)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0: cells[lab[i][j]].add((i,j))
    layer=[[None]*w for _ in range(h)]
    cmap=[[] for _ in range(n)]
    rem=[set(c) for c in cells]
    l=0
    while any(rem):
        for L in range(n):
            if not rem[L]: continue
            boundary={(a,b) for (a,b) in rem[L] if any((a+di,b+dj) not in rem[L] for di,dj in((1,0),(-1,0),(0,1),(0,-1)))}
            col=grid[next(iter(boundary))[0]][next(iter(boundary))[1]]
            assert all(grid[a][b]==col for a,b in boundary)
            cmap[L].append(col)
            for a,b in boundary: layer[a][b]=l
            rem[L]-=boundary
        l+=1
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0:
                L=lab[i][j]; k=layer[i][j]
                out[i][j]=cmap[L][len(cmap[L])-1-k]
    return out
