def rings(grid):
    """Reverse the ring colors of each nested single-color-ring object, keeping geometry."""
    h,w=len(grid),len(grid[0])
    lab=[[-1]*w for _ in range(h)]; n=0
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0 and lab[i][j]==-1:
                qq=deque([(i,j)]); lab[i][j]=n
                while qq:
                    a,b=qq.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and grid[na][nb]!=0 and lab[na][nb]==-1:
                            lab[na][nb]=n; qq.append((na,nb))
                n+=1
    rem=[set() for _ in range(n)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0: rem[lab[i][j]].add((i,j))
    ringidx=[[-1]*w for _ in range(h)]
    ringcols=[[] for _ in range(n)]
    l=0
    while any(rem):
        for L in range(n):
            if not rem[L]: continue
            boundary={(a,b) for (a,b) in rem[L] if any((a+di,b+dj) not in rem[L] for di,dj in((1,0),(-1,0),(0,1),(0,-1)))}
            col=grid[next(iter(boundary))[0]][next(iter(boundary))[1]]
            if not ringcols[L] or ringcols[L][-1]!=col: ringcols[L].append(col)
            R=len(ringcols[L])-1
            for a,b in boundary: ringidx[a][b]=R
            rem[L]-=boundary
        l+=1
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0:
                cols=ringcols[lab[i][j]]
                out[i][j]=cols[len(cols)-1-ringidx[i][j]]
    return out
